def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x] and not seen[y][x]:
                col=g[y][x]; st=[(y,x)]; cells=set()
                seen[y][x]=True
                while st:
                    a,b=st.pop()
                    cells.add((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p,q=a+dy,b+dx
                        if 0<=p<H and 0<=q<W and g[p][q]==col and not seen[p][q]:
                            seen[p][q]=True; st.append((p,q))
                out.append((col,cells))
    return out
