def sim(g):
    H,W=len(g),len(g[0])
    cs=comps(g)
    placed={}  # comp -> current occupied cells
    occ=set()
    for col,cells in cs:
        cur={(y,x) for y,x in cells}; occ|=cur
        placed[(col,tuple(sorted(cells)))]=cur
    changed=True
    while changed:
        changed=False
        for i,(col,orig) in enumerate(cs):
            cur=placed[(col,orig)]
            newc={(y,x+1) for y,x in cur}
            if all(0<=p[1]<W for p in newc) and not (newc&occ-newc)==set() and not any((py,px) in occ-{cell} and False for py,px in newc):
                pass
        # simpler: try each object one step; only move if ALL of its new cells free in occ excluding its own cur cells
        for idx in range(len(cs)):
            col,orig=cs[idx]; cur=placed[(col,orig)]
            newc={(y,x+1) for y,x in cur}
            other=occ-cur
            if all(0<=p[1]<W for p in newc) and not (newc & other):
                occ-=cur; occ|=newc
                placed[(col,orig)]=newc
                changed=True
    o=[[0]*W for _ in range(H)]
    for (col,orig),cur in placed.items():
        for y,x in cur: o[y][x]=col
    return o
