# Fix sim bug: when moving object i, only remove ITS own cur cells and keep others.
def sim2(g):
    H,W=len(g),len(g[0])
    cs=[(col,tuple(sorted(cells))) for col,cells in comps(g)]
    placed={}; occ=set()
    for i in range(len(cs)):
        placed[i]=set(cs[i][1]); occ|=placed[i]
    changed=True
    while changed:
        changed=False
        for i in range(len(cs)):
            col,orig=cs[i]; cur=placed[i]
            newc={(y,x+1) for y,x in cur}
            other=occ-cur
            if all(0<=p[1]<W for p in newc) and not (newc & other):
                occ-=cur; occ|=newc
                placed[i]=newc
                changed=True
    o=[[0]*W for _ in range(H)]
    for i,(col,orig) in enumerate(cs):
        for y,x in placed[i]: o[y][x]=col
    return o
